import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.ClgMjOt7.js";const _=JSON.parse('{"title":"ログインとアカウント設定","description":"Pixiv アカウントでのログインと複数アカウントの切り替え","frontmatter":{"title":"ログインとアカウント設定","description":"Pixiv アカウントでのログインと複数アカウントの切り替え"},"headers":[],"relativePath":"user/authentication.md","filePath":"user/authentication.md","lastUpdated":1789107345000}'),l={name:"user/authentication.md"};function o(n,a,h,s,d,c){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="ログインとアカウント設定" tabindex="-1">ログインとアカウント設定 <a class="header-anchor" href="#ログインとアカウント設定" aria-label="Permalink to &quot;ログインとアカウント設定&quot;">​</a></h1><p>Palleria を使用するには Pixiv アカウントでログインが必要です。</p><hr><h2 id="ログイン手順" tabindex="-1">ログイン手順 <a class="header-anchor" href="#ログイン手順" aria-label="Permalink to &quot;ログイン手順&quot;">​</a></h2><p>アプリを起動するとログイン選択画面が表示されます。</p><h3 id="_1-web-ログイン-通常はこちら" tabindex="-1">1. Web ログイン (通常はこちら) <a class="header-anchor" href="#_1-web-ログイン-通常はこちら" aria-label="Permalink to &quot;1. Web ログイン (通常はこちら)&quot;">​</a></h3><ol><li><strong>「Web ログイン」</strong> をタップします。</li><li>Pixiv の公式ログイン画面が開くので、メールアドレスとパスワードを入力してログインします（Google / Apple などの連携アカウントも利用できます）。</li><li>ログインに成功すると、自動的に Palleria の画面に戻り準備が完了します。</li></ol><h3 id="_2-リフレッシュトークンでログイン-上級者向け" tabindex="-1">2. リフレッシュトークンでログイン (上級者向け) <a class="header-anchor" href="#_2-リフレッシュトークンでログイン-上級者向け" aria-label="Permalink to &quot;2. リフレッシュトークンでログイン (上級者向け)&quot;">​</a></h3><p>すでに Pixiv の <code>refresh_token</code> を所持している場合は、トークン文字を直接入力してログインすることも可能です。</p><hr><h2 id="安全性について" tabindex="-1">安全性について <a class="header-anchor" href="#安全性について" aria-label="Permalink to &quot;安全性について&quot;">​</a></h2><p>ログイン時に入力したパスワードが Palleria 側に保存されることはありません。ログイン後に発行される認証コードのみが、スマホ内の安全な領域（暗号化ストレージ）に保存されます。</p><hr><h2 id="複数アカウントの切り替え" tabindex="-1">複数アカウントの切り替え <a class="header-anchor" href="#複数アカウントの切り替え" aria-label="Permalink to &quot;複数アカウントの切り替え&quot;">​</a></h2><p>家族用や用途別に複数のアカウントをお持ちの場合、ログイン状態を保持したまま切り替えることができます。</p><ul><li>アカウント設定画面や、メニューのアカウント切り替えシートからいつでも別のアカウントに切り替えが可能です。</li><li>アカウントごとに個別でログアウトすることもできます。</li></ul>',16)])])}const p=e(l,[["render",o]]);export{_ as __pageData,p as default};
